const API = {
  async get(path) { return this.request(path); },
  async post(path, body) { return this.request(path, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)}); },
  async patch(path, body) { return this.request(path, {method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)}); },
  async request(path, options={}) {
    let response;
    try { response = await fetch(path, options); }
    catch { throw new Error('The API could not be reached. Check the service connection and try again.'); }
    const data = await response.json().catch(()=>({}));
    if (!response.ok) {
      const err = data.error || {};
      if (response.status===503 && err.code==='model_artifacts_unavailable') throw new Error('Inference is unavailable because model artifacts are not loaded. The API is running, but no prediction was created.');
      if (response.status===422) throw new Error((err.details||[]).map(x=>`${x.location?.slice(-1)[0]||'Input'}: ${x.message}`).join(' · ') || err.message || 'The request is invalid.');
      if (response.status===401) { if(path!=='/v1/auth/login') showLogin(); throw new Error(path==='/v1/auth/login'?'Username or password is incorrect.':'Authentication required.'); }
      throw new Error(err.message || `API request failed (${response.status}).`);
    }
    return data;
  }
};
