function geographicLocations(records) {
  return records.filter(
    record => Number.isFinite(record.latitude) && Number.isFinite(record.longitude),
  );
}

function latestGeographicRecords(records) {
  const latest = new Map();
  for (const record of records) {
    const identity = record.cell || `${record.latitude},${record.longitude}`;
    if (!identity || identity === 'null,null' || latest.has(identity)) continue;
    latest.set(identity, record);
  }
  return [...latest.values()];
}

function geographicPositions(records) {
  const latitudes = records.map(record => Number(record.latitude));
  const longitudes = records.map(record => Number(record.longitude));
  const minLatitude = Math.min(...latitudes);
  const maxLatitude = Math.max(...latitudes);
  const minLongitude = Math.min(...longitudes);
  const maxLongitude = Math.max(...longitudes);

  return records.map(record => {
    const latitude = Number(record.latitude);
    const longitude = Number(record.longitude);
    return {
      record,
      latitude,
      longitude,
      x: maxLongitude === minLongitude
        ? 50
        : 8 + ((longitude - minLongitude) / (maxLongitude - minLongitude)) * 84,
      y: maxLatitude === minLatitude
        ? 50
        : 88 - ((latitude - minLatitude) / (maxLatitude - minLatitude)) * 76,
    };
  });
}

function geographicLegend() {
  return `<div class="network-summary geographic-legend" aria-label="Prediction status legend">
    <span class="legend-normal"><i class="legend-dot"></i>NORMAL</span>
    <span class="legend-review"><i class="legend-dot"></i>Review Required</span>
    <span class="legend-fault"><i class="legend-dot"></i>FAULT</span>
  </div>`;
}

function geographicPlot(records, variant = '') {
  const points = geographicPositions(geographicLocations(records));
  if (!points.length) return '';

  const markers = points.map(({record, latitude, longitude, x, y}) => `
    <button type="button" class="geo-point ${esc(record.status)}"
      style="left:${x}%;top:${y}%" data-record="${record.prediction_id}"
      data-tip="${esc(record.cell || 'Unassigned')} · ${esc(record.status)} · ${latitude.toFixed(4)}, ${longitude.toFixed(4)}"
      aria-label="Open ${esc(record.cell || 'unassigned prediction')}, ${esc(record.status)}, latitude ${latitude}, longitude ${longitude}">
      <i></i>
      <span class="sr-only">${esc(record.cell || 'Site')} ${esc(record.status)} at ${latitude}, ${longitude}</span>
    </button>`).join('');

  return `<div class="geo-plot ${variant}" role="group" aria-label="Prediction coordinates by longitude and latitude">
    ${markers}
    <div class="geo-axis" aria-hidden="true"><span class="lat">LATITUDE</span><span class="lon">LONGITUDE</span></div>
  </div>`;
}
