function networkHealthCustomizerOptions(config){
  const context=config.selectedVisualization;
  const status=context==='network-status';
  const item=config.visualizations.find(value=>value.id===context);
  const definitions=status?nhStatuses:nhCauses;
  const categories=definitions.map(([id,label])=>'<label class="nh-choice"><input type="checkbox" data-nh-category value="'+id+'" '+(item.categories.includes(id)?'checked':'')+'><span>'+label+'</span></label>').join('');
  const chartTypes=status?['donut','bar']:['bar'];
  const charts=chartTypes.map(type=>'<label class="nh-radio-choice"><input type="radio" name="nh-chart-type" value="'+type+'" '+(item.chartType===type?'checked':'')+'><span>'+(type==='donut'?'Donut':'Bar')+'</span></label>').join('');
  return '<fieldset><legend>Categories</legend><div class="nh-choice-grid">'+categories+'</div><small class="nh-field-note">'+(status?'Select at least two status categories.':'Counts include only results with Fault status.')+'</small></fieldset><fieldset><legend>Chart type</legend><div class="nh-radio-grid">'+charts+'</div></fieldset>';
}
function wireNetworkHealthCustomizer(){
  const modal=el('#nh-customizer');
  if(!modal||modal.dataset.wired==='true')return;
  modal.dataset.wired='true';
  const close=()=>{modal.hidden=true;el('#nh-open-customizer')?.focus()};
  const select=el('#nh-visualization-select');
  const options=el('#nh-customizer-options');
  const error=el('#nh-config-error');
  const refresh=()=>{
    select.value=nhDraft.selectedVisualization;
    options.innerHTML=networkHealthCustomizerOptions(nhDraft);
    error.textContent='';
    options.querySelectorAll('[data-nh-category]').forEach(input=>input.addEventListener('change',()=>{
      const item=nhDraft.visualizations.find(value=>value.id===nhDraft.selectedVisualization);
      item.categories=[...options.querySelectorAll('[data-nh-category]:checked')].map(value=>value.value);
      if(nhDraft.selectedVisualization==='network-status'&&item.categories.length<2)error.textContent='Select at least two Network Status categories.';
      else if(nhDraft.selectedVisualization==='fault-causes'&&item.categories.length<1)error.textContent='Select at least one fault cause.';
      else error.textContent='';
    }));
    options.querySelectorAll('[name="nh-chart-type"]').forEach(input=>input.addEventListener('change',()=>{
      const item=nhDraft.visualizations.find(value=>value.id===nhDraft.selectedVisualization);
      item.chartType=input.value;
    }));
  };
  el('#nh-open-customizer')?.addEventListener('click',()=>{
    nhDraft=JSON.parse(JSON.stringify(nhPreference));
    refresh();
    modal.hidden=false;
    select.focus();
  });
  select.addEventListener('change',()=>{
    nhDraft.selectedVisualization=select.value;
    refresh();
  });
  modal.querySelectorAll('[data-nh-cancel]').forEach(button=>button.addEventListener('click',close));
  modal.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close()}});
  el('#nh-apply')?.addEventListener('click',()=>{
    const item=nhDraft.visualizations.find(value=>value.id===nhDraft.selectedVisualization);
    item.categories=[...options.querySelectorAll('[data-nh-category]:checked')].map(value=>value.value);
    const chart=options.querySelector('[name="nh-chart-type"]:checked');
    if(chart)item.chartType=chart.value;
    const valid=validateVisualizationConfig(nhDraft);
    if(!valid){
      error.textContent=nhDraft.selectedVisualization==='network-status'?'Select at least two Network Status categories.':'Select at least one fault cause.';
      return;
    }
    if(!saveVisualizationPreferences(valid)){error.textContent='The preference could not be saved in this browser.';return}
    close();
    el('#view').innerHTML=networkHealthPage();
    wire();
  });
  el('#nh-reset')?.addEventListener('click',()=>{
    resetVisualizationPreferences();
    close();
    el('#view').innerHTML=networkHealthPage();
    wire();
  });
}

